export interface PartyDetails {
  nome: string;
  nacionalidade: string;
  estadoCivil: string;
  profissao: string;
  rg: string;
  cpfCnpj: string;
  endereco: {
    rua: string;
    numero: string;
    bairro: string;
    cidade: string;
    uf: string;
    cep: string;
  };
}

export interface ServiceDetails {
  objeto: string;
  valor: string;
  prazo: string;
  dataInicio: string;
  multa: string;
  foro: string;
}

export interface ContractData {
  contratante: PartyDetails;
  contratado: PartyDetails;
  servico: ServiceDetails;
}

