import React from 'react';
import { ContractData, PartyDetails, ServiceDetails } from '../types';

interface ContractFormProps {
  data: ContractData;
  onChange: (newData: ContractData) => void;
  onPrint: () => void;
}

export const ContractForm: React.FC<ContractFormProps> = ({ data, onChange, onPrint }) => {
  const [agreed, setAgreed] = React.useState(false);

  const updateContratante = (field: string, value: string) => {
    onChange({
      ...data,
      contratante: { ...data.contratante, [field]: value }
    });
  };

  const updateContratanteAddress = (field: string, value: string) => {
    onChange({
      ...data,
      contratante: {
        ...data.contratante,
        endereco: { ...data.contratante.endereco, [field]: value }
      }
    });
  };

  const updateContratado = (field: string, value: string) => {
    onChange({
      ...data,
      contratado: { ...data.contratado, [field]: value }
    });
  };

  const updateContratadoAddress = (field: string, value: string) => {
    onChange({
      ...data,
      contratado: {
        ...data.contratado,
        endereco: { ...data.contratado.endereco, [field]: value }
      }
    });
  };

  const updateServico = (field: string, value: string) => {
    onChange({
      ...data,
      servico: { ...data.servico, [field]: value }
    });
  };

  return (
    <div className="bg-white rounded-lg shadow-md p-6 border border-gray-200">
      <h2 className="text-xl font-semibold text-navy-900 mb-6 border-b pb-2">1. Preencha os Dados</h2>

      {/* CONTRATANTE */}
      <section className="mb-8">
        <h3 className="text-lg font-medium text-blue-800 mb-4 bg-blue-50 p-2 rounded">Dados do Contratante (Cliente)</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="col-span-1 md:col-span-2">
            <label className="block text-sm font-medium text-gray-700 mb-1">Nome Completo / Razão Social</label>
            <input 
              type="text" 
              className="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
              value={data.contratante.nome}
              onChange={(e) => updateContratante('nome', e.target.value)}
              placeholder="Ex: João da Silva"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">CPF / CNPJ</label>
            <input 
              type="text" 
              className="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
              value={data.contratante.cpfCnpj}
              onChange={(e) => updateContratante('cpfCnpj', e.target.value)}
              placeholder="000.000.000-00"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">RG (Opcional)</label>
            <input 
              type="text" 
              className="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
              value={data.contratante.rg}
              onChange={(e) => updateContratante('rg', e.target.value)}
            />
          </div>
          <div>
             <label className="block text-sm font-medium text-gray-700 mb-1">Nacionalidade</label>
            <input 
              type="text" 
              className="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
              value={data.contratante.nacionalidade}
              onChange={(e) => updateContratante('nacionalidade', e.target.value)}
            />
          </div>
          <div>
             <label className="block text-sm font-medium text-gray-700 mb-1">Estado Civil</label>
            <select 
              className="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
              value={data.contratante.estadoCivil}
              onChange={(e) => updateContratante('estadoCivil', e.target.value)}
            >
              <option value="">Selecione...</option>
              <option value="Solteiro(a)">Solteiro(a)</option>
              <option value="Casado(a)">Casado(a)</option>
              <option value="Divorciado(a)">Divorciado(a)</option>
              <option value="Viúvo(a)">Viúvo(a)</option>
            </select>
          </div>
          <div>
             <label className="block text-sm font-medium text-gray-700 mb-1">Profissão</label>
