              onChange={(e) => updateContratante('profissao', e.target.value)}
            />
          </div>
        </div>

        <div className="mt-4">
          <label className="block text-sm font-medium text-gray-700 mb-2">Endereço Completo</label>
          <div className="grid grid-cols-1 md:grid-cols-6 gap-3">
