               <input placeholder="Número" className="w-full border border-gray-300 rounded px-3 py-2 text-sm" value={data.contratante.endereco.numero} onChange={(e) => updateContratanteAddress('numero', e.target.value)} />
             </div>
             <div className="md:col-span-2">
               <input placeholder="Bairro" className="w-full border border-gray-300 rounded px-3 py-2 text-sm" value={data.contratante.endereco.bairro} onChange={(e) => updateContratanteAddress('bairro', e.target.value)} />
             </div>
             <div className="md:col-span-2">
               <input placeholder="Cidade" className="w-full border border-gray-300 rounded px-3 py-2 text-sm" value={data.contratante.endereco.cidade} onChange={(e) => updateContratanteAddress('cidade', e.target.value)} />
             </div>
             <div className="md:col-span-1">
               <input placeholder="UF" maxLength={2} className="w-full border border-gray-300 rounded px-3 py-2 text-sm" value={data.contratante.endereco.uf} onChange={(e) => updateContratanteAddress('uf', e.target.value)} />
             </div>
             <div className="md:col-span-1">
               <input placeholder="CEP" className="w-full border border-gray-300 rounded px-3 py-2 text-sm" value={data.contratante.endereco.cep} onChange={(e) => updateContratanteAddress('cep', e.target.value)} />
             </div>
          </div>
        </div>
      </section>

      {/* CONTRATADO */}
      <section className="mb-8">
        <h3 className="text-lg font-medium text-blue-800 mb-4 bg-blue-50 p-2 rounded">Dados do Contratado (Prestador)</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="col-span-1 md:col-span-2">
            <label className="block text-sm font-medium text-gray-700 mb-1">Nome Completo / Razão Social</label>
            <input 
              type="text" 
              className="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
              value={data.contratado.nome}
              onChange={(e) => updateContratado('nome', e.target.value)}
              placeholder="Ex: Prestadora XYZ Ltda"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">CPF / CNPJ</label>
            <input 
              type="text" 
              className="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
              value={data.contratado.cpfCnpj}
              onChange={(e) => updateContratado('cpfCnpj', e.target.value)}
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">RG (Opcional)</label>
            <input 
              type="text" 
              className="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
              value={data.contratado.rg}
              onChange={(e) => updateContratado('rg', e.target.value)}
            />
          </div>
          <div>
             <label className="block text-sm font-medium text-gray-700 mb-1">Nacionalidade</label>
            <input 
              type="text" 
              className="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
              value={data.contratado.nacionalidade}
              onChange={(e) => updateContratado('nacionalidade', e.target.value)}
            />
          </div>
          <div>
             <label className="block text-sm font-medium text-gray-700 mb-1">Estado Civil</label>
            <select 
              className="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
              value={data.contratado.estadoCivil}
              onChange={(e) => updateContratado('estadoCivil', e.target.value)}
            >
              <option value="">Selecione...</option>
              <option value="Solteiro(a)">Solteiro(a)</option>
              <option value="Casado(a)">Casado(a)</option>
              <option value="Divorciado(a)">Divorciado(a)</option>
              <option value="Viúvo(a)">Viúvo(a)</option>
            </select>
          </div>
          <div>
             <label className="block text-sm font-medium text-gray-700 mb-1">Profissão</label>
            <input 
              type="text" 
              className="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
              value={data.contratado.profissao}
              onChange={(e) => updateContratado('profissao', e.target.value)}
            />
          </div>
        </div>

        <div className="mt-4">
          <label className="block text-sm font-medium text-gray-700 mb-2">Endereço Completo</label>
          <div className="grid grid-cols-1 md:grid-cols-6 gap-3">
             <div className="md:col-span-4">
               <input placeholder="Rua / Avenida" className="w-full border border-gray-300 rounded px-3 py-2 text-sm" value={data.contratado.endereco.rua} onChange={(e) => updateContratadoAddress('rua', e.target.value)} />
             </div>
             <div className="md:col-span-2">
               <input placeholder="Número" className="w-full border border-gray-300 rounded px-3 py-2 text-sm" value={data.contratado.endereco.numero} onChange={(e) => updateContratadoAddress('numero', e.target.value)} />
             </div>
             <div className="md:col-span-2">
               <input placeholder="Bairro" className="w-full border border-gray-300 rounded px-3 py-2 text-sm" value={data.contratado.endereco.bairro} onChange={(e) => updateContratadoAddress('bairro', e.target.value)} />
             </div>
             <div className="md:col-span-2">
               <input placeholder="Cidade" className="w-full border border-gray-300 rounded px-3 py-2 text-sm" value={data.contratado.endereco.cidade} onChange={(e) => updateContratadoAddress('cidade', e.target.value)} />
             </div>
             <div className="md:col-span-1">
               <input placeholder="UF" maxLength={2} className="w-full border border-gray-300 rounded px-3 py-2 text-sm" value={data.contratado.endereco.uf} onChange={(e) => updateContratadoAddress('uf', e.target.value)} />
             </div>
             <div className="md:col-span-1">
               <input placeholder="CEP" className="w-full border border-gray-300 rounded px-3 py-2 text-sm" value={data.contratado.endereco.cep} onChange={(e) => updateContratadoAddress('cep', e.target.value)} />
