      </div>
    </div>
  );
};

import React from 'react';
import { ContractData, PartyDetails } from '../types';

interface ContractPreviewProps {
  data: ContractData;
}

export const ContractPreview: React.FC<ContractPreviewProps> = ({ data }) => {
  const { contratante, contratado, servico } = data;

  const formatDate = (dateString: string) => {
    if (!dateString) return '_____ de ________________ de ______';
    const date = new Date(dateString);
    return date.toLocaleDateString('pt-BR', { day: 'numeric', month: 'long', year: 'numeric' });
  };

  const renderAddress = (p: PartyDetails) => {
    const parts = [
      p.endereco.rua && `${p.endereco.rua}`,
      p.endereco.numero && `nº ${p.endereco.numero}`,
      p.endereco.bairro && `Bairro ${p.endereco.bairro}`,
      p.endereco.cidade && `${p.endereco.cidade}`,
      p.endereco.uf && `${p.endereco.uf}`,
      p.endereco.cep && `CEP ${p.endereco.cep}`
    ].filter(Boolean);

    return parts.length > 0 ? parts.join(', ') : '_______________________________________________________ (Endereço Completo)';
  };

  const renderParty = (p: PartyDetails) => {
    const hasData = p.nome || p.cpfCnpj;

    if (!hasData) return <span className="text-gray-400 italic">[Preencha os dados ao lado]</span>;

    return (
      <span className="font-bold text-black">
        {p.nome || '___________'}, {p.nacionalidade || '___________'}, {p.estadoCivil || '___________'}, {p.profissao || '___________'}, 
        portador(a) do RG nº {p.rg || '___________'} e inscrito(a) no CPF/CNPJ sob o nº {p.cpfCnpj || '___________'}, 
        residente e domiciliado(a) na {renderAddress(p)}.
      </span>
    );
  };

  return (
    <div className="sticky top-4">
      <div className="bg-gray-200 p-4 rounded-t-lg md:hidden print:hidden text-center text-sm font-semibold text-gray-700">
        Pré-visualização do Documento
      </div>

      {/* A4 Container */}
      <div id="contract-paper" className="bg-white shadow-2xl mx-auto p-[2.5cm] min-h-[29.7cm] text-justify text-sm leading-relaxed text-black font-serif print:shadow-none print:w-full print:absolute print:top-0 print:left-0 print:m-0 print:p-[2cm]">

        <h1 className="text-center font-bold text-lg uppercase mb-8">CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>

        <p className="mb-4">
          Pelo presente instrumento particular, de um lado:
        </p>

        <p className="mb-4">
          <strong>CONTRATANTE:</strong> {renderParty(contratante)}
        </p>

        <p className="mb-4">
          <strong>CONTRATADO:</strong> {renderParty(contratado)}
        </p>

        <p className="mb-6">
          Têm entre si, justo e contratado, o que se segue:
        </p>

        <h2 className="font-bold uppercase mb-2">CLÁUSULA PRIMEIRA - DO OBJETO</h2>
        <p className="mb-4">
          O presente contrato tem por objeto a prestação de serviços de: <span className="font-bold">{servico.objeto || '_______________________________________________________'}</span>, a ser realizado pelo CONTRATADO ao CONTRATANTE, de acordo com as especificações ajustadas entre as partes.
        </p>

        <h2 className="font-bold uppercase mb-2">CLÁUSULA SEGUNDA - DO VALOR E FORMA DE PAGAMENTO</h2>
        <p className="mb-4">
          Pelos serviços prestados, o CONTRATANTE pagará ao CONTRATADO a quantia total de <span className="font-bold">R$ {servico.valor || '0,00'}</span>.
        </p>

        <h2 className="font-bold uppercase mb-2">CLÁUSULA TERCEIRA - DO PRAZO</h2>
        <p className="mb-4">
          O prazo para execução dos serviços será de <span className="font-bold">{servico.prazo || '_______'}</span>, iniciando-se em <span className="font-bold">{servico.dataInicio ? new Date(servico.dataInicio).toLocaleDateString('pt-BR') : '__/__/____'}</span>.
        </p>

        <h2 className="font-bold uppercase mb-2">CLÁUSULA QUARTA - DAS OBRIGAÇÕES</h2>
        <p className="mb-4">
          O CONTRATADO obriga-se a prestar os serviços com zelo, diligência e técnica adequada, cumprindo os prazos estipulados. O CONTRATANTE obriga-se a efetuar o pagamento na forma e condições acordadas e a fornecer as informações necessárias para a execução do serviço.
        </p>

        <h2 className="font-bold uppercase mb-2">CLÁUSULA QUINTA - DA RESCISÃO E MULTA</h2>
        <p className="mb-4">
          O descumprimento de qualquer cláusula deste contrato implicará na sua rescisão imediata, sujeitando a parte infratora ao pagamento de multa equivalente a <span className="font-bold">{servico.multa}</span> sobre o valor do contrato, sem prejuízo de perdas e danos.
        </p>
        <p className="mb-4">
          A prestação de serviço é regida pelos artigos 593 a 609 do Código Civil Brasileiro (Lei nº 10.406/2002).
        </p>

        <h2 className="font-bold uppercase mb-2">CLÁUSULA SEXTA - DO FORO</h2>
        <p className="mb-8">
          Para dirimir quaisquer controvérsias oriundas do CONTRATO, as partes elegem o foro da comarca de <span className="font-bold">{servico.foro || '_________________'}</span>.
        </p>

        <p className="mb-12 text-center">
          E, por estarem assim justos e contratados, assinam o presente instrumento em 02 (duas) vias de igual teor.
        </p>

        <p className="text-right mb-16">
          {servico.foro || 'Local'}, {formatDate(new Date().toISOString())}.
