          <div className="text-center">
            <div className="border-t border-black pt-2 mb-1 w-3/4 mx-auto"></div>
            <span className="block text-xs">Testemunha 2 (CPF: _______________)</span>
          </div>
        </div>

      </div>
    </div>
  );
};

