            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 lg:gap-12 items-start">
              <div className="order-1 lg:order-1 print:hidden">
                <ContractForm 
                  data={contractData} 
                  onChange={handleDataChange} 
                  onPrint={handlePrint}
                />
